import { ApplicationConfig } from '@angular/core';
import {
  provideHttpClient,
  withFetch,
  withInterceptors,
} from '@angular/common/http';
import { authInterceptor } from './auth.interceptor';

// Modern setup: HttpClient comes from a provider, not a module
export const appConfig: ApplicationConfig = {
  providers: [
    provideHttpClient(withFetch(), withInterceptors([authInterceptor])),
  ],
};

import { HttpInterceptorFn } from '@angular/common/http';

// Functional interceptor: clone the request and add the header
export const authInterceptor: HttpInterceptorFn = (req, next) => {
  const token = localStorage.getItem('token');
  if (!token) {
    return next(req);
  }

  return next(
    req.clone({ setHeaders: { Authorization: `Bearer ${token}` } }),
  );
};

import { Component, inject } from '@angular/core';
import { FormControl } from '@angular/forms';
import { HttpClient } from '@angular/common/http';
import { toSignal } from '@angular/core/rxjs-interop';
import { Observable, debounceTime, distinctUntilChanged, switchMap } from 'rxjs';
import { Product } from './product.service';

@Component({
  selector: 'app-search',
  template: `
    <input [formControl]="query" placeholder="Search" />
    @for (product of results(); track product.id) {
      <p>{{ product.name }}</p>
    }
  `,
})
export class SearchComponent {
  private readonly http = inject(HttpClient);

  readonly query = new FormControl('', { nonNullable: true });

  private search(term: string): Observable<Product[]> {
    return this.http.get<Product[]>('https://api.shop.dev/products', {
      params: { q: term },
    });
  }

  // switchMap cancels the previous request when a new term arrives
  readonly results = toSignal(
    this.query.valueChanges.pipe(
      debounceTime(300),
      distinctUntilChanged(),
      switchMap((term) => this.search(term)),
    ),
    { initialValue: [] as Product[] },
  );
}

import { Component, inject } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { interval } from 'rxjs';
import { ThemeService } from './theme.service';

@Component({ selector: 'app-clock', template: '{{ tick }}' })
export class ClockComponent {
  private readonly theme = inject(ThemeService);
  tick = 0;

  constructor() {
    // Automatically unsubscribes when the component is destroyed
    interval(1000)
      .pipe(takeUntilDestroyed())
      .subscribe((value) => (this.tick = value));

    this.theme.theme$.pipe(takeUntilDestroyed()).subscribe(console.log);
  }
}

